"""UUID v7 identifiers for Mantle tracker events."""

from __future__ import annotations

import secrets
import time
import uuid

_UUID7_TIMESTAMP_BITS = 48
_UUID7_VERSION = 0x7
_UUID7_RAND_A_MASK = 0xFFF
_UUID7_VARIANT = 0b10
_UUID7_RAND_B_MASK = (1 << 62) - 1
_MAX_UUID7_TIMESTAMP_MS = 1 << _UUID7_TIMESTAMP_BITS


def new_event_id() -> str:
    """Returns a new UUID v7 string for a Mantle tracker event.

    Uses ``uuid.uuid7`` on Python 3.13+ and an RFC 9562 helper on 3.11/3.12.

    Returns:
        Canonical UUID string (8-4-4-4-12).
    """
    uuid7 = getattr(uuid, "uuid7", None)
    if uuid7 is not None:
        return str(uuid7())
    return str(_uuid7())


def _uuid7() -> uuid.UUID:
    return _uuid7_from_unix_ms(
        time.time_ns() // 1_000_000,
        secrets.randbits(12),
        secrets.randbits(62),
    )


def _uuid7_from_unix_ms(timestamp_ms: int, rand_a: int, rand_b: int) -> uuid.UUID:
    """Pack a UUID v7 from a millisecond timestamp and random bits.

    Args:
        timestamp_ms: Unix time in milliseconds. Must fit in 48 bits.
        rand_a: Random bits stored in the 12-bit ``rand_a`` field.
        rand_b: Random bits stored in the 62-bit ``rand_b`` field.

    Returns:
        A version-7 UUID.

    Raises:
        ValueError: If ``timestamp_ms`` is outside the UUID v7 range.
    """
    if timestamp_ms < 0 or timestamp_ms >= _MAX_UUID7_TIMESTAMP_MS:
        raise ValueError("UUID v7 timestamp must fit in 48 bits.")

    packed = (
        (timestamp_ms << 80)
        | (_UUID7_VERSION << 76)
        | ((rand_a & _UUID7_RAND_A_MASK) << 64)
        | (_UUID7_VARIANT << 62)
        | (rand_b & _UUID7_RAND_B_MASK)
    )
    return uuid.UUID(int=packed)
